import type { Booking, Prisma } from '@prisma/client';
import { prisma } from '../../db/client.js';
import { BOOKING_ACTIVE } from './schema.js';

export type Client = Prisma.TransactionClient | typeof prisma;

export interface BookingData {
  roomId: string;
  userId: string;
  title: string;
  startsAt: Date;
  endsAt: Date;
}

export interface BookingFilter {
  roomId?: string;
  userId?: string;
  status?: string;
  from?: Date;
  to?: Date;
  limit: number;
  offset: number;
}

export function create(data: BookingData, client: Client = prisma): Promise<Booking> {
  return client.booking.create({ data });
}

export function findConflict(
  roomId: string,
  startsAt: Date,
  endsAt: Date,
  excludeId?: string,
  client: Client = prisma,
): Promise<Booking | null> {
  return client.booking.findFirst({
    where: {
      roomId,
      status: BOOKING_ACTIVE,
      startsAt: { lt: endsAt },
      endsAt: { gt: startsAt },
      ...(excludeId ? { id: { not: excludeId } } : {}),
    },
  });
}

export function findById(id: string, client: Client = prisma): Promise<Booking | null> {
  return client.booking.findUnique({ where: { id } });
}

export function listActiveInRange(roomId: string, from: Date, to: Date): Promise<Booking[]> {
  return prisma.booking.findMany({
    where: {
      roomId,
      status: BOOKING_ACTIVE,
      startsAt: { lt: to },
      endsAt: { gt: from },
    },
    orderBy: { startsAt: 'asc' },
  });
}

